// TypeScript port of shared/protocol (SWP). Byte-for-byte compatible with the C++
// reference implementation (verified against fixtures.json generated by tests/host).

export const SERVICE_UUID = "7a1e0001-5c3b-4f8e-9d2a-6b1e5a7c0de0";
export const RX_UUID = "7a1e0002-5c3b-4f8e-9d2a-6b1e5a7c0de0";
export const TX_UUID = "7a1e0003-5c3b-4f8e-9d2a-6b1e5a7c0de0";
export const INFO_UUID = "7a1e0004-5c3b-4f8e-9d2a-6b1e5a7c0de0";

export const PROTOCOL_VERSION = 1;
export const MAX_PAYLOAD = 4096;

export function crc16(data: Uint8Array, crc = 0xffff): number {
  for (const b of data) {
    crc ^= b << 8;
    for (let i = 0; i < 8; i++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
  }
  return crc;
}

const enc = new TextEncoder();
const dec = new TextDecoder();

function utf8Prefix(s: string, max: number): Uint8Array {
  let b = enc.encode(s);
  if (b.length <= max) return b;
  let n = max;
  while (n > 0 && (b[n] & 0xc0) === 0x80) n--;
  return b.subarray(0, n);
}

export class Writer {
  private buf: number[] = [];
  u8(v: number) { this.buf.push(v & 0xff); return this; }
  u16(v: number) { return this.u8(v).u8(v >> 8); }
  u32(v: number) { return this.u16(v & 0xffff).u16((v >>> 16) & 0xffff); }
  i8(v: number) { return this.u8(v < 0 ? v + 256 : v); }
  i32(v: number) { return this.u32(v >>> 0); }
  str8(s: string) { const b = utf8Prefix(s, 255); this.u8(b.length); b.forEach((x) => this.buf.push(x)); return this; }
  str16(s: string, max = 0xffff) { const b = utf8Prefix(s, max); this.u16(b.length); b.forEach((x) => this.buf.push(x)); return this; }
  bytes(b: Uint8Array) { b.forEach((x) => this.buf.push(x)); return this; }
  done(): Uint8Array { return Uint8Array.from(this.buf); }
}

export class Reader {
  private p = 0;
  failed = false;
  constructor(private b: Uint8Array) {}
  private need(n: number): boolean {
    if (this.failed || this.p + n > this.b.length) { this.failed = true; return false; }
    return true;
  }
  get remaining() { return this.failed ? 0 : this.b.length - this.p; }
  u8(): number { return this.need(1) ? this.b[this.p++] : 0; }
  u16(): number { const a = this.u8(); return a | (this.u8() << 8); }
  u32(): number { const a = this.u16(); return (a | (this.u16() << 16)) >>> 0; }
  u64(): bigint { const lo = BigInt(this.u32()); return lo | (BigInt(this.u32()) << 32n); }
  i8(): number { const v = this.u8(); return v > 127 ? v - 256 : v; }
  i16(): number { const v = this.u16(); return v > 32767 ? v - 65536 : v; }
  i32(): number { return this.u32() | 0; }
  raw(n: number): Uint8Array { if (!this.need(n)) return new Uint8Array(); const r = this.b.slice(this.p, this.p + n); this.p += n; return r; }
  str8(): string { return dec.decode(this.raw(this.u8())); }
  str16(max = 0xffff): string { const n = this.u16(); if (n > max) { this.failed = true; return ""; } return dec.decode(this.raw(n)); }
}

export interface Frame { type: number; seq: number; payload: Uint8Array; }

export function encodeFrame(type: number, seq: number, payload: Uint8Array): Uint8Array {
  if (payload.length > MAX_PAYLOAD) throw new Error("payload too large");
  const out = new Uint8Array(10 + payload.length);
  out.set([0xa5, 0x5a, PROTOCOL_VERSION, type, seq & 0xff, (seq >> 8) & 0xff, payload.length & 0xff, payload.length >> 8]);
  out.set(payload, 8);
  const crc = crc16(out.subarray(2, 8 + payload.length));
  out[8 + payload.length] = crc & 0xff;
  out[9 + payload.length] = crc >> 8;
  return out;
}

/** Incremental decoder with magic-byte resynchronisation (mirrors swp::FrameDecoder). */
export class FrameDecoder {
  private buf = new Uint8Array(0);
  crcErrors = 0;
  feed(data: Uint8Array) {
    const n = new Uint8Array(this.buf.length + data.length);
    n.set(this.buf);
    n.set(data, this.buf.length);
    this.buf = n.length > 2 * (MAX_PAYLOAD + 10) ? new Uint8Array(0) : n;
  }
  next(): Frame | null {
    for (;;) {
      let s = 0;
      while (s + 1 < this.buf.length && !(this.buf[s] === 0xa5 && this.buf[s + 1] === 0x5a)) s++;
      if (s + 1 >= this.buf.length && this.buf.length > 0 && this.buf[this.buf.length - 1] !== 0xa5) s = this.buf.length;
      this.buf = this.buf.subarray(s);
      if (this.buf.length < 8) return null;
      const len = this.buf[6] | (this.buf[7] << 8);
      if (len > MAX_PAYLOAD) { this.buf = this.buf.subarray(2); continue; }
      const total = 10 + len;
      if (this.buf.length < total) return null;
      const want = this.buf[total - 2] | (this.buf[total - 1] << 8);
      if (crc16(this.buf.subarray(2, total - 2)) !== want) { this.crcErrors++; this.buf = this.buf.subarray(2); continue; }
      const f: Frame = { type: this.buf[3], seq: this.buf[4] | (this.buf[5] << 8), payload: this.buf.slice(8, 8 + len) };
      const version = this.buf[2];
      this.buf = this.buf.subarray(total);
      if (version !== PROTOCOL_VERSION) continue;
      return f;
    }
  }
}
